    <style>
        .plpHeroCont .plp-hero-container {
            padding-top: 0px;
        }
        div[class^="styles_PlpHeaderWrapper"]:has(div[class*="_plphero"]) {
            position: relative;
            padding-top: 32px;

        }

        div[class^="styles_PlpHeaderWrapper"]:has(div[class*="_plpslider"]) .plpHeroCont .plp-hero-container {

            /* extra padding if slider is present */
            padding-bottom: 32px;

        }

        div[class^="styles_PlpHeaderWrapper"]:has(div[aria-label="Breadcrumb Navigation"]) .plpHeroCont .plp-hero-container {

            /* account for breadcrumbs */
            padding-top: 0px;

        }



        /* Breadcrumbs */
        div[class*="styles_PlpHeaderWrapper"] div[aria-label="Breadcrumb Navigation"] {
            position: relative;
            z-index: 10;
            background: transparent;
            padding: 8px 16px 0 16px;
            margin: 0 auto !important;
            width: 100% !important;
            height: auto;
            display: flex;
            justify-content: center;
            align-items: flex-start;

        }

        div[class*="styles_PlpHeaderWrapper"] div[aria-label="Breadcrumb Navigation"] ul {
            padding: 8px 0;
            font-size: 12px;
            line-height: 16px;
            text-align: center;

        }

        div[class*="styles_PlpHeaderWrapper"] div[aria-label="Breadcrumb Navigation"] ul li {
            height: unset;
            color: #737168;
            font-weight: 400;
            text-wrap: nowrap;

            &:last-of-type {
                font-weight: 400;

            }


        }

        div[class*="styles_PlpHeaderWrapper"] div[aria-label="Breadcrumb Navigation"] ul li a {
            color: #0065d1;
            text-decoration: underline;

            &:hover {
                text-decoration: none;

            }


        }

        div[class*="styles_PlpHeaderWrapper"] div[aria-label="Breadcrumb Navigation"] ul #chevronSquare {
            filter: none !important;

            & path {
                fill: #737168;

            }


        }



        /* End Breadcrumbs */
        .plpHeroCont {
            background-color: #f6f6f4;

        }

        .plp-hero-heading,
        .plp-hero-seo-copy,
        .plp-hero-tab {
            color: #1e1d19;

        }

        .plp-hero-heading {
            margin: 8px auto;
            font-size: 2em;

        }

        .plpHeroCont .plp-hero-cta.green {
            color: #4f6b57;
            border-color: #4f6b57;
            background-color: transparent;

        }

        .plpHeroCont .plp-hero-cta.green:hover {
            color: #ffffff;
            background-color: #4f6b57;

        }

        .plp-hero-tabs.green_theme {
            margin: 0px auto 8px;
            display: flex;
            justify-content: center;
            align-items: center;
            background: #4F6B57;
            width: 100%;
            padding-top: 8px;

        }


        @media (max-width: 768px) {
            .Cab .green_theme .plp-hero-tab {
                font-size: 14px;
            }
        }

        .green_theme .plp-hero-tab { 
            padding: 8px 24px;
            border-radius: 8px 8px 0 0;
            margin-bottom: -2px;
            color: #ffffff;
            position:relative;
            margin-left:2px ;        
            text-decoration: none;
			font-size: 16px;
			line-height: 24px;
        }

        .green_theme .plp-hero-tab.active {

            color: #1E1D19;
            background-color: #f6f6f4;
            background: #F6F6F4;            
            padding: 8px 24px;
			font-weight: 700;
