			margin-bottom: 24px;
            background-color: #F6F6F4;
            width: 100%;
            display: flex;
            flex-direction: column;
			gap: var(--400, 16px);
            position: relative;
        }

        .title-and-crumbs {
            margin-left: 16px;
        }

        .slider-bread-crumbs {
            margin-bottom: 32px;
            display: flex;
            flex-direction: row;
            align-items: center;
            justify-content: space-between;
            width: 198px;
        }

        .crumb-arrow {
            height: 8px;
            width: 8px;
        }

        .slider-bread-crumb-link {
            color: #0065D1;
            font-size: 12px;
        }

        .slider-bread-crumb-link {
            color: #0065D1;
            font-size: 12px;
        }

        .slider-bread-crumb-link-current {
            color: #656464;
            font-size: 12px;
