        .small-slider-card {
            height: 160px;
            width: 160px;
            min-width: 160px;
            background-color: #FFF;
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: flex-end;
            flex-direction: column;
            margin-right: 16px;
