            .slider-scrollview::-webkit-scrollbar-thumb {
                width: 4px;
                background-color: #C3C0B4;
                border-radius: 4px;
            }

            /* Start */
            .first-slider-card {
                margin-left: 16px;
            }

            .arrow-row {
                display: none !important;
            }

			.plp-boat-instock {
				padding: var(--200, 8px) var(--400, 16px);
			}

			.plp-boat-instock-title {
				font-size: 32px;
				font-height: 32px;
			}			
        }

        .slider-arrow-hide {
            display: none;
        }

        .slider-arrow-show {
            display: flex;
            position: absolute;
            right: 0;
            bottom: -30px;
        }

