        function scrollView(direction) {
            var maxScrollLeft = document.getElementsByClassName("slider-scrollview")[0].scrollWidth - document.getElementsByClassName("slider-scrollview")[0].clientWidth; var amountScrolled = 0; if (direction == "right") {
                document.getElementById('left-arrow').style.opacity = 1;
                // Scroll the User to the right when the right icon is pressed            
                if (window.innerWidth > 1200) {
                    amountScrolled = 2000
                    document.getElementsByClassName("slider-scrollview")[0].scrollLeft += 2000;
                } else {
                    amountScrolled = 500
                    document.getElementsByClassName("slider-scrollview")[0].scrollLeft += 600;
                }
                // Gray out the right icon when the end of the view is reached            
                if (document.getElementsByClassName("slider-scrollview")[0].scrollLeft + amountScrolled >= maxScrollLeft) {
                    document.getElementById('right-arrow').style.opacity = 0.2
                } else {
                    document.getElementById('right-arrow').style.opacity = 1
                }
            } else {
                document.getElementById('right-arrow').style.opacity = 1;
                // Scroll the user to the right when the right icon is pressed            
                if (window.innerWidth > 1200) {
                    amountScrolled = 2000
                    document.getElementsByClassName("slider-scrollview")[0].scrollLeft -= 2000;
                } else {
                    amountScrolled = 600
                    document.getElementsByClassName("slider-scrollview")[0].scrollLeft -= 600;
                }
                // Gray out the left icon when the start of the view is reached            
                if (document.getElementsByClassName("slider-scrollview")[0].scrollLeft - amountScrolled <= 0) {
                    document.getElementById('left-arrow').style.opacity = 0.2
                } else {
                    document.getElementById('right-arrow').style.opacity = 1
                }
            }
        }
        // Update the arrows when the user is naturally scrolling    
        function updateArrows() {
            var maxScrollLeft = document.getElementsByClassName("slider-scrollview")[0].scrollWidth - document.getElementsByClassName("slider-scrollview")[0].clientWidth;        // console.log("Current Scroll " + parseInt(document.getElementsByClassName("slider-scrollview")[0].scrollLeft))
            // console.log("Max Scroll " + maxScrollLeft)
            if (parseInt(document.getElementsByClassName("slider-scrollview")[0].scrollLeft) == 0) {
                document.getElementById('left-arrow').style.opacity = 0.2
                document.getElementById('right-arrow').style.opacity = 1
            } if (parseInt(document.getElementsByClassName("slider-scrollview")[0].scrollLeft) == maxScrollLeft) {
                document.getElementById('left-arrow').style.opacity = 1;
                document.getElementById('right-arrow').style.opacity = 0.2;
            }
        }
        // Highlight current PLP card based on URL        
